#include "trim.hpp"
#include <cstring>
int main(){try{auto a=attachedModel(),b=trimModel();auto&x=a.mechanics;auto&y=b.mechanics;need(x.bodyNames==y.bodyNames&&x.jointNames==y.jointNames&&x.shapeNames==y.shapeNames&&x.defaultQ==y.defaultQ&&x.defaultV==y.defaultV,"topology changed");need(x.collisionExclusions.size()==y.collisionExclusions.size(),"exclusion count changed");for(unsigned i=0;i<x.collisionExclusions.size();++i)need(x.collisionExclusions[i].colliderA==y.collisionExclusions[i].colliderA&&x.collisionExclusions[i].colliderB==y.collisionExclusions[i].colliderB,"exclusion changed");for(unsigned i=0;i<x.bodies.size();i++)need(std::memcmp(&x.bodies[i],&y.bodies[i],sizeof(x.bodies[i]))==0,"body changed");for(unsigned i=0;i<x.joints.size();i++)need(std::memcmp(&x.joints[i],&y.joints[i],sizeof(x.joints[i]))==0,"joint changed");for(unsigned i=0;i<x.dofs.size();i++)need(std::memcmp(&x.dofs[i],&y.dofs[i],sizeof(x.dofs[i]))==0,"DOF changed");unsigned edited=0;for(unsigned i=0;i<x.shapes.size();i++){const auto&u=x.shapes[i];const auto&v=y.shapes[i];bool target=x.shapeNames[i]=="crow_left_shank/collision"||x.shapeNames[i]=="crow_right_shank/collision";if(target){edited++;need(std::abs((v.localPosition.z-v.dimensions.z)-(u.localPosition.z-u.dimensions.z)-.006f)<1e-7,"bottom trim");need(std::abs((v.localPosition.z+v.dimensions.z)-(u.localPosition.z+u.dimensions.z))<1e-7,"top moved");auto z=v;z.localPosition.z=u.localPosition.z;z.dimensions.z=u.dimensions.z;z.contactRestAndBoundingRadius.z=u.contactRestAndBoundingRadius.z;need(std::memcmp(&u,&z,sizeof(u))==0,"unexpected shank shape change");}else need(std::memcmp(&u,&v,sizeof(u))==0,"other shape changed");}need(edited==2&&y.defaultV.size()==40,"wrong edited shape count");std::cout<<"edited_shank_shapes "<<edited<<" lower_end_reduction_m 0.006 upper_end_unchanged 1 unchanged_collision_exclusions "<<x.collisionExclusions.size()<<" unchanged_bodies "<<x.bodies.size()<<" unchanged_joints "<<x.joints.size()<<" unchanged_dofs "<<x.dofs.size()<<"\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
